const Imap = require('imap');
const { simpleParser } = require('mailparser');
const iconv = require('iconv-lite');
require('iconv-lite/encodings');

// Функция для перемещения письма в папку
function moveEmail(imap, uid, folder) {
    return new Promise((resolve, reject) => {
        imap.move(uid, folder, (err) => {
            if (err) {
                console.error(`Ошибка перемещения письма ${uid} в папку ${folder}:`, err);
                reject(err);
            } else {
                console.log(`Письмо ${uid} перемещено в папку: ${folder}`);
                resolve();
            }
        });
    });
}

// Основная функция для обработки писем
function fetchAndProcessEmails(imap_host, imap_port, imap_user, imap_pass, emails, limit = 50) {
    return new Promise((resolve, reject) => {
        const results = [];
        const imap = new Imap({
            user: imap_user,
            password: imap_pass,
            host: imap_host,
            port: parseInt(imap_port),
            tls: true
        });

        imap.once('ready', function () {
            imap.openBox('Рассылки|Входящие', false, function (err, box) { // false - для чтения и записи
                if (err) return reject(err);

                // Ищем прочитанные письма
                imap.search(['SEEN'], async function (err, uids) {
                    if (err) return reject(err);

                    if (!uids.length) {
                        imap.end();
                        return resolve([]);
                    }

                    console.log(`Найдено прочитанных писем: ${uids.length}`);

                    // Разбиваем на группы по 100 писем
                    const chunkSize = 100;
                    const chunks = [];
                    for (let i = 0; i < Math.min(uids.length, limit); i += chunkSize) {
                        chunks.push(uids.slice(i, i + chunkSize));
                    }

                    console.log(`Разбиваем на ${chunks.length} групп по ${chunkSize} писем`);

                    try {
                        // Обрабатываем каждую группу последовательно
                        for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex++) {
                            const chunkUids = chunks[chunkIndex];
                            console.log(`Обрабатываем группу ${chunkIndex + 1}/${chunks.length} (${chunkUids.length} писем)`);

                            const chunkResults = await processChunk(imap, chunkUids, emails);
                            results.push(...chunkResults);

                            console.log(`Группа ${chunkIndex + 1} обработана`);
                        }

                        console.log('Все группы обработаны, найдено писем:', results.length);
                        imap.end();
                        resolve(results);
                    } catch (error) {
                        console.error('Ошибка при обработке групп:', error);
                        imap.end();
                        reject(error);
                    }
                });
            });
        });

        // Функция для обработки группы писем
        async function processChunk(imap, uids, emails) {
            return new Promise((resolve, reject) => {
                const chunkResults = [];
                let processed = 0;

                const f = imap.fetch(uids, { 
                    bodies: '',
                    struct: true 
                });

                f.on('message', function (msg) {
                    let buffer = Buffer.alloc(0);
                    let uid;

                    msg.on('attributes', attrs => {
                        uid = attrs.uid;
                    });

                    msg.on('body', function (stream) {
                        const chunks = [];
                        stream.on('data', chunk => chunks.push(chunk));
                        stream.on('end', () => {
                            buffer = Buffer.concat(chunks);
                        });
                    });

                    msg.once('end', async function () {
                        try {
                            let parsed = await simpleParser(buffer);

                            if (parsed.text && /пї|Рї|СЂ|Сѓ/.test(parsed.text)) {
                                const decoded = iconv.decode(buffer, 'win1251');
                                parsed = await simpleParser(decoded);
                            }

                            const sender = parsed.from?.value?.[0]?.address || '';
                            const isInEmailList = emails.includes(sender);

                            // Определяем папку для перемещения
                            const targetFolder = isInEmailList 
                                ? 'Рассылки|Прогрев' 
                                : 'Рассылки|Обработано ИИ';

                            // Перемещаем письмо
                            try {
                                await moveEmail(imap, uid, targetFolder);
                            } catch (moveError) {
                                console.error(`Не удалось переместить письмо ${uid}:`, moveError);
                            }

                            chunkResults.push({
                                id: chunkResults.length + 1,
                                sender: sender,
                                recipient: parsed.to?.value?.[0]?.address || '',
                                message_id: parsed.messageId || '',
                                folder: targetFolder,
                                uid: uid,
                                is_in_list: isInEmailList
                            });

                            console.log(`Письмо ${uid} от ${sender} → ${targetFolder}`);

                        } catch (e) {
                            console.error('Ошибка парсинга письма UID:', uid, e);
                        } finally {
                            processed++;

                            // Если все письма в группе обработаны
                            if (processed === uids.length) {
                                resolve(chunkResults);
                            }
                        }
                    });
                });

                f.once('error', err => {
                    console.error('Ошибка fetch для группы:', err);
                    reject(err);
                });

                f.once('end', function () {
                    console.log('Fetch группы завершен');
                });
            });
        }

        imap.once('error', err => reject(err));
        imap.connect();
    });
}

const lst = [];
for (const item of $input.all()) {
    try {
        const { emails, imap_host, imap_port, imap_user, imap_pass } = item.json;

        // Преобразуем emails в массив, если это строка
        const emailList = Array.isArray(emails) ? emails : 
                         emails ? emails.split(',').map(email => email.trim()) : [];

        console.log(`Список emails для проверки: ${emailList.join(', ')}`);
        console.log(`Обрабатываем аккаунт: ${imap_user}`);

        const res = await fetchAndProcessEmails(imap_host, imap_port, imap_user, imap_pass, emailList, 5000);
        lst.push(...res);

    } catch (error) {
        console.error(`Ошибка для аккаунта ${item.json.imap_user}:`, error);
    }
}

console.log(`Итого обработано писем: ${lst.length}`);
return lst;
